package stream

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
)

// This file records the pack's codec truth at publish (playback-capability-gate
// D2): after the build publishes, each variant playlist is probed with ffprobe
// — the MP4 muxer, not the source, decides the sample entries — and the probe
// facts compose RFC 6381 codec parameter strings through the pure table below.
// The probe targets the published playlist rather than the bare EXT-X-MAP init
// segment because ffprobe's stream facts (profile, level) only resolve once the
// init's avcC/hvcC extradata is readable WITH media — a bare init reports
// level -99 and no profile, which would fail-open every real pack. The
// composition is strictly fail-open: any probe failure or any stream the table
// cannot compose degrades the whole record to absent (nil), so an unprobeable
// build mounts exactly as it did before this record existed — never a failed
// pack, never a wrong refusal.

// avc1Profiles maps the ffprobe h264 profile spelling to the RFC 6381
// avc1.PPCCLL prefix it composes: profile_idc plus the constraint-flags byte
// (the AVCDecoderConfigurationRecord bytes ffprobe does not expose, pinned per
// profile to the de-facto constants browsers compose — baseline packs set no
// constraint flags, constrained baseline sets constraint_set1 (40), Main sets
// constraint_set1 (40, the x264/Apple convention), High sets none). The level
// byte composes from ffprobe's level int. A profile outside the table (High10
// and friends — none of which the classifier ever packs) composes nothing.
var avc1Profiles = map[string]string{
	"Baseline":             "4200",
	"Constrained Baseline": "4240",
	"Main":                 "4D40",
	"High":                 "6400",
}

// hevcProfiles maps the ffprobe hevc profile spelling to its RFC 6381
// general_profile_idc and general_profile_compatibility_flags nibble (the
// canonical Main=1.6 / Main10=2.4 pair the hevc sample entries carry in the
// wild). The remaining segments compose from ffprobe facts: the sample-entry
// tag itself (codec_tag_string — hvc1 or hev1, the muxer's choice, read from
// the probed artifact rather than guessed), the level as L<level_idc> (ffprobe
// reports HEVC level_idc directly: 93=3.1, 120=4.0, 153=5.1), and the
// constraint suffix B0 (progressive, non-packed, frame-only — the universal
// progressive-source constant). A profile outside the table composes nothing.
var hevcProfiles = map[string][2]string{
	"Main":    {"1", "6"},
	"Main 10": {"2", "4"},
}

// codecString composes one probed stream's RFC 6381 codec parameter string
// through the table — exactly the classifier-admitted families (avc1,
// hvc1/hev1, mp4a.40.2, opus, flac, ac-3, ec-3, mp3, vorbis); anything else,
// or any fact the family needs and ffprobe did not report, composes "" and the
// caller degrades the record. Pure.
func codecString(s map[string]any) string {
	switch streamCodec(s) {
	case "h264":
		prefix, ok := avc1Profiles[streamProfile(s)]
		if !ok {
			return ""
		}
		lv := streamLevel(s)
		if lv == 0 {
			return ""
		}
		return fmt.Sprintf("avc1.%s%02X", prefix, lv)
	case "hevc":
		tag, _ := s["codec_tag_string"].(string)
		if tag != "hvc1" && tag != "hev1" {
			return ""
		}
		pc, ok := hevcProfiles[streamProfile(s)]
		if !ok {
			return ""
		}
		lv := streamLevel(s)
		if lv == 0 {
			return ""
		}
		return fmt.Sprintf("%s.%s.%s.L%d.B0", tag, pc[0], pc[1], lv)
	case "aac":
		if streamProfile(s) == "LC" {
			return "mp4a.40.2"
		}
		return ""
	case "mp3":
		return "mp3"
	case "opus":
		return "opus"
	case "flac":
		return "flac"
	case "ac3":
		return "ac-3"
	case "eac3":
		return "ec-3"
	case "vorbis":
		return "vorbis"
	default:
		return ""
	}
}

// streamProfile reads a stream's profile, trimmed (facts are verbatim — never
// trust the source's whitespace). Pure.
func streamProfile(s map[string]any) string {
	p, _ := s["profile"].(string)
	return strings.TrimSpace(p)
}

// streamLevel reads a stream's level as a positive int (ffprobe reports it as
// a JSON number; an unreadable level reads -99 or is absent). 0 means "no
// usable level" and composes nothing. Pure.
func streamLevel(s map[string]any) int {
	lv, ok := s["level"].(float64)
	if !ok || lv < 1 || lv > 255 {
		return 0
	}
	return int(lv)
}

// buildCodecs composes the published build's codec record: every variant
// playlist is probed (the only I/O — one ffprobe per variant), the table
// composes each stream — all video strings first, then the audio strings in
// the pinned rendition order (embedded audio first, then the voiceovers, the
// variant order the master playlist declares) — and duplicates collapse,
// first occurrence winning. Any failure (an unreadable playlist, a failed or
// empty probe, one uncomposable stream) returns nil: the record degrades to
// absent and Pack still succeeds. Never mutates the build.
func (s *Service) buildCodecs(ctx context.Context, buildDir string, vs []variantPlaylist) []string {
	var videos, audios []string
	for _, v := range vs {
		playlist := filepath.Join(buildDir, v.rel, "index.m3u8")
		streams, err := s.probeMediaStreams(ctx, playlist)
		if err != nil {
			return nil
		}
		sawVideo := false
		for _, st := range streams {
			cs := codecString(st)
			if cs == "" {
				return nil // one stream the table cannot compose degrades the record
			}
			switch st["codec_type"] {
			case "video":
				videos = append(videos, cs)
				sawVideo = true
			case "audio":
				audios = append(audios, cs)
			default:
				return nil // the pack lane publishes video/audio only; anything else is unreadable
			}
		}
		if !sawVideo && len(audios) == 0 {
			return nil
		}
	}
	ordered := make([]string, 0, len(videos)+len(audios))
	ordered = append(ordered, videos...)
	ordered = append(ordered, audios...)
	return dedupeCodecs(ordered)
}

// legacyCodecs composes one pre-record build's codec strings read-side
// (playback-capability-gate D2 — the LEGACY FALLBACK): the same table as the
// publish path, over the item's STORED SOURCE ffprobe facts, which a remux
// carries into the pack. Exactly the pack lane's map is composed — the first
// video stream (-map 0:v:0) and every audio stream (-map 0:a; subtitle and
// data streams are dropped, so they are never judged); videos first, then
// audio in file order, duplicates collapsing. One video/audio stream the
// table cannot compose (or no decidable picture at all) degrades the whole
// record to nil — fail-open, the field is simply absent, never a wrong
// answer. Pure.
func legacyCodecs(ffprobe any) []string {
	f, ok := ffprobe.(map[string]any)
	if !ok {
		return nil
	}
	video, audio := videoAudioStreams(f["streams"])
	if video == nil {
		return nil // the pack lane never publishes a video-less build
	}
	out := make([]string, 0, 1+len(audio))
	for _, st := range append([]map[string]any{video}, audio...) {
		cs := codecString(st)
		if cs == "" {
			return nil // one uncomposable stream degrades the record (same table spirit)
		}
		out = append(out, cs)
	}
	return dedupeCodecs(out)
}

// dedupeCodecs collapses duplicate codec strings keeping the first
// occurrence, in order; an empty result composes nil (the absent record).
func dedupeCodecs(in []string) []string {
	out := make([]string, 0, len(in))
	seen := map[string]bool{}
	for _, cs := range in {
		if seen[cs] {
			continue
		}
		seen[cs] = true
		out = append(out, cs)
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// probeMediaStreams ffprobes one media path — a published variant playlist or
// init segment — and returns its streams array in the verbatim -show_streams
// JSON shape (the same shape the stored ffprobe facts carry). ffprobe ships
// with ffmpeg and resolves on PATH; the exec is arg-slice only (the runFFmpeg
// discipline) and bounded by the caller's context plus PackTimeout.
func (s *Service) probeMediaStreams(ctx context.Context, path string) ([]map[string]any, error) {
	bin, err := exec.LookPath("ffprobe")
	if err != nil {
		return nil, fmt.Errorf("stream: ffprobe not found: %w", err)
	}
	pctx, cancel := context.WithTimeout(ctx, s.PackTimeout)
	defer cancel()
	cmd := exec.CommandContext(pctx, bin, "-v", "error", "-show_streams", "-of", "json", path)
	out, err := cmd.Output()
	if err != nil {
		diag := ""
		var ee *exec.ExitError
		if errors.As(err, &ee) {
			diag = ": " + truncateTail(ee.Stderr, 512)
		}
		return nil, fmt.Errorf("stream: ffprobe %s: %w%s", filepath.Base(path), err, diag)
	}
	var doc struct {
		Streams []map[string]any `json:"streams"`
	}
	if err := json.Unmarshal(out, &doc); err != nil {
		return nil, fmt.Errorf("stream: ffprobe %s json: %w", filepath.Base(path), err)
	}
	return doc.Streams, nil
}
